8|// Two audio elements with equal-power crossfades. Volume lives in a
9|// ref, so the slider never re-runs the track effect or touches src.
10|// Nothing plays before the first user press. Reduced motion only
11|// affects visuals; the audio fade always runs its full length.
12|export function Player({
13|  track,
14|  fadeSec,
15|  sceneTitle,
16|  soundtrackName,
17|  isFallback,
18|  canSkip,
19|  onSkip,
20|  mixOn,
21|  onToggleMix,
22|  styles,
23|  styleId,
24|  onStyleChange,
25|  onEnded,
26|  playlistOn,
27|  playlistLabel,
28|  onTogglePlaylist,
29|  controlsDisabled,
30|}: {
31|  track: Track | null;
32|  fadeSec: number;
33|  sceneTitle: string | null;
34|  soundtrackName: string | null;
35|  isFallback: boolean;
36|  canSkip: boolean;
37|  onSkip: () => void;
38|  mixOn: boolean;
39|  onToggleMix: () => void;
40|  styles: StyleInfo[];
41|  styleId: string | null;
42|  onStyleChange: (style: string) => void;
43|  onEnded: (trackId: string) => void;
44|  playlistOn: boolean;
45|  playlistLabel: string | null;
46|  onTogglePlaylist: () => void;
47|  controlsDisabled: boolean;
