50|  const secondRef = useRef<HTMLAudioElement | null>(null);
51|  const audibleRef = useRef(0);
52|  const levelRef = useRef<[number, number]>([1, 0]);
53|  const volumeRef = useRef(0.8);
54|  const fadeRef = useRef<number | null>(null);
55|  const loopArmedRef = useRef<string | null>(null);
56|  const trackRef = useRef<Track | null>(track);
57|  trackRef.current = track;
58|  const fadeSecRef = useRef(fadeSec);
59|  fadeSecRef.current = fadeSec;
60|  const onEndedRef = useRef(onEnded);
61|  onEndedRef.current = onEnded;
62|  const playingRef = useRef(false);
63|  const startedRef = useRef(false);
64|  const firstPlayRef = useRef(true);
65|
66|  // Scheduler fade when set, else the config default; never 0 mid session.
67|  function loopFadeSec() {
68|    return fadeSecRef.current > 0 ? fadeSecRef.current : MUSIC_CONFIG.crossfadeSec;
69|  }
70|  const [started, setStarted] = useState(false);
71|  const [playing, setPlaying] = useState(false);
72|  const [volume, setVolume] = useState(0.8);
73|  const requestPlayRef = useRef((_: Track, __: number) => {});
74|
75|  const [reducedMotion, setReducedMotion] = useState(
76|    () =>
77|      typeof window !== "undefined" &&
78|      !!window.matchMedia?.("(prefers-reduced-motion: reduce)").matches,
79|  );
80|
81|  useEffect(() => {
82|    const query = window.matchMedia?.("(prefers-reduced-motion: reduce)");
83|    if (!query) return;
84|    const onChange = (event: MediaQueryListEvent) => setReducedMotion(event.matches);
85|    query.addEventListener("change", onChange);
86|    return () => query.removeEventListener("change", onChange);
87|  }, []);
88|
89|  function applyLevels() {
90|    const els = [firstRef.current, secondRef.current];
91|    els.forEach((el, i) => {
92|      if (el) el.volume = Math.min(1, Math.max(0, (levelRef.current[i] ?? 0) * volumeRef.current));
93|    });
94|  }
95|
96|  function cancelFade() {
97|    if (fadeRef.current !== null) {
98|      cancelAnimationFrame(fadeRef.current);
99|      fadeRef.current = null;
100|    }
101|  }
102|
103|  // Assigned each render so handlers always see fresh refs. Fades from
104|  // the currently louder element to the newest track; a mid-fade request
105|  // cancels the pending fade and starts from current levels.
106|  requestPlayRef.current = (next: Track, durSec: number) => {
107|    const els = [firstRef.current, secondRef.current];
108|    const srcIdx = (levelRef.current[0] ?? 0) >= (levelRef.current[1] ?? 0) ? 0 : 1;
109|    const dstIdx = 1 - srcIdx;
110|    const srcEl = els[srcIdx];
111|    const dst = els[dstIdx];
112|    if (!srcEl || !dst) return;
113|    cancelFade();
114|    if (trackRef.current?.id !== next.id) loopArmedRef.current = null;
115|    trackRef.current = next;
116|    dst.src = next.src;
117|    dst.onloadedmetadata = () => {
118|      if (next.startSec > 0 && Number.isFinite(dst.duration) && next.startSec < dst.duration) {
119|        try {
120|          dst.currentTime = next.startSec;
121|        } catch {
122|          // Past the end; leave playback at zero.
123|        }
124|      }
125|    };
126|    if (!playingRef.current || durSec <= 0) {
127|      levelRef.current = [0, 0];
128|      levelRef.current[dstIdx] = 1;
129|      audibleRef.current = dstIdx;
