140|    const tick = (now: number) => {
141|      // Pause freezes the fade; resume continues from the frozen point.
142|      if (!playingRef.current) {
143|        t0 += now - prev;
144|        prev = now;
145|        fadeRef.current = requestAnimationFrame(tick);
146|        return;
147|      }
148|      prev = now;
149|      const t = Math.min(1, (now - t0) / (durSec * 1000));
