153|      if (t < 1) {
154|        fadeRef.current = requestAnimationFrame(tick);
155|        return;
156|      }
157|      fadeRef.current = null;
158|      levelRef.current[srcIdx] = 0;
159|      levelRef.current[dstIdx] = 1;
160|      audibleRef.current = dstIdx;
161|      applyLevels();
162|      srcEl.pause();
163|    };
164|    fadeRef.current = requestAnimationFrame(tick);
165|  };
