167|  const trackId = track?.id ?? null;
168|  useEffect(() => {
169|    const next = trackRef.current;
170|    if (!started || !next) {
171|      // Before the first press, swaps only change src.
172|      if (!started && next) {
173|        const el = [firstRef.current, secondRef.current][audibleRef.current];
174|        if (el && !el.src.endsWith(next.src)) el.src = next.src;
175|      }
176|      return;
177|    }
178|    // The single start path: fade 0 on the very first press.
179|    const dur = firstPlayRef.current ? 0 : fadeSecRef.current;
180|    firstPlayRef.current = false;
181|    requestPlayRef.current(next, dur);
182|  }, [started, trackId]);
183|
184|  useEffect(() => cancelFade, []);
