186|  function handleTimeUpdate(index: number, el: HTMLAudioElement) {
187|    const next = trackRef.current;
188|    // A playlist track always runs to its end so the scheduler advances.
189|    if (!next || !next.loop || playlistOn || index !== audibleRef.current) return;
190|    const fade = loopFadeSec();
191|    const duration = el.duration;
192|    if (!Number.isFinite(duration) || duration <= fade * 2) return;
193|    const remain = duration - el.currentTime;
194|    if (remain <= fade && loopArmedRef.current !== next.id) {
195|      loopArmedRef.current = next.id;
196|      requestPlayRef.current(next, fade);
197|    } else if (remain > fade + 1) {
198|      loopArmedRef.current = null;
199|    }
200|  }
201|
202|  function handleEnded(index: number) {
203|    const els = [firstRef.current, secondRef.current];
204|    // An element that ends while a fade is running is the one fading out.
205|    if (index !== audibleRef.current || fadeRef.current !== null) {
206|      els[index]?.pause();
207|      return;
208|    }
209|    const next = trackRef.current;
210|    if (!next) return;
211|    if (next.loop && !playlistOn) {
212|      requestPlayRef.current(next, loopFadeSec());
213|      return;
214|    }
215|    onEndedRef.current(next.id);
216|  }
217|
218|  function toggle() {
219|    const both = [firstRef.current, secondRef.current];
220|    if (!startedRef.current) {
221|      startedRef.current = true;
222|      setStarted(true);
223|      playingRef.current = true;
224|      setPlaying(true);
225|      return;
226|    }
227|    if (playingRef.current) {
228|      for (const el of both) el?.pause();
229|      playingRef.current = false;
230|      setPlaying(false);
231|      return;
232|    }
233|    playingRef.current = true;
234|    setPlaying(true);
235|    let heard = false;
236|    both.forEach((el, i) => {
237|      if (el && (levelRef.current[i] ?? 0) > 0.02) {
238|        heard = true;
239|        void el.play().catch(() => undefined);
240|      }
241|    });
242|    const next = trackRef.current;
243|    if (!heard && next) requestPlayRef.current(next, 0);
244|  }
245|
246|  function changeVolume(value: number) {
247|    setVolume(value);
248|    volumeRef.current = value;
249|    applyLevels();
250|  }
251|
252|  const credit = track ? [track.composer, track.artist].filter(Boolean).join(", ") : "";
